#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupDisplayTask final {
public:
 enum class Kind {ClearSelection,Refresh,Program,Label};
 enum class Stage {Retain,Clear,Publish,Restore,Return,BindProgram,ReadMode,SetMode,ReadEdit,SelectEdit,ClearHigh,ReadSelection,SelectSelection,TestMode,SelectMode,OtherMode,BindLabel,ReadDemo,SelectDemo,BindDemo,DemoText,SkipLabel,LabelChild,ReadBank,AsciiBank,BankCharacter,ReadProgram,ProgramNumber,ClearSelection,WriteSelection,ReadWriteMode,SelectWriteMode,BindWrite,DecrementWriteMode,SelectWriteLabel,BindOverwrite,OverwriteTail,ReadEditMode,SelectEditMode,BindCursor,CursorTail,LabelTail,Complete};
 StartupDisplayTask(Kind kind=Kind::ClearSelection):kind_(kind),stage_(kind==Kind::ClearSelection?Stage::Retain:kind==Kind::Refresh?Stage::BindProgram:kind==Kind::Program?Stage::BindLabel:Stage::ReadWriteMode){}
 Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}uint8_t value()const{return value_;}uint8_t mode()const{return mode_;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Retain:return c.pushWord;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;case Stage::Publish:case Stage::WriteSelection:return 9+c.write;case Stage::BindProgram:case Stage::BindLabel:case Stage::BindDemo:case Stage::BindWrite:case Stage::BindOverwrite:return 9;case Stage::ReadMode:return 12+c.read;case Stage::ReadEdit:case Stage::ReadSelection:case Stage::ReadDemo:case Stage::ReadBank:case Stage::ReadProgram:case Stage::ReadWriteMode:case Stage::ReadEditMode:return 9+c.read;case Stage::SetMode:case Stage::DemoText:case Stage::BankCharacter:case Stage::ProgramNumber:return c.call;case Stage::LabelChild:return c.shortCall;case Stage::SelectEdit:case Stage::SelectSelection:case Stage::SelectMode:case Stage::OtherMode:case Stage::SelectWriteLabel:case Stage::OverwriteTail:case Stage::CursorTail:case Stage::LabelTail:return 8;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Retain:break;case Stage::Clear:value_=0;break;case Stage::Publish:write(0);break;case Stage::Return:next=Stage::Complete;break;case Stage::ReadMode:mode_=uint8_t(read());break;case Stage::SetMode:waiting_=true;break;case Stage::ReadEdit:case Stage::ReadSelection:case Stage::ReadDemo:case Stage::ReadBank:case Stage::ReadProgram:case Stage::ReadWriteMode:case Stage::ReadEditMode:value_=uint8_t(read());break;case Stage::SelectEdit:if(value_)next=Stage::Complete;break;case Stage::SelectSelection:if(value_)next=Stage::Complete;break;case Stage::SelectMode:next=mode_?Stage::OtherMode:Stage::Complete;break;case Stage::OtherMode:next=Stage::Complete;break;case Stage::SelectDemo:if(!value_)next=Stage::LabelChild;break;case Stage::DemoText:waiting_=true;break;case Stage::SkipLabel:next=Stage::ReadBank;break;case Stage::LabelChild:waiting_=true;break;case Stage::BankCharacter:case Stage::ProgramNumber:waiting_=true;break;case Stage::ClearSelection:value_=0;break;case Stage::WriteSelection:write(0);next=Stage::Return;break;case Stage::SelectWriteMode:if(!value_)next=Stage::ReadEditMode;break;case Stage::DecrementWriteMode:--value_;break;case Stage::SelectWriteLabel:if(!value_)next=Stage::Complete;break;case Stage::OverwriteTail:case Stage::CursorTail:case Stage::LabelTail:next=Stage::Complete;break;case Stage::SelectEditMode:if(!value_)next=Stage::LabelTail;break;default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_;uint8_t value_=0,mode_=0;bool waiting_=false;
};
}
